use std::{
    fs::{self, File, OpenOptions},
    io,
    path::{Path, PathBuf},
};

use serde::Serialize;
use uuid::Uuid;

use crate::store::{Error, Result, Store};

#[derive(Debug, Clone, Serialize)]
pub struct RestoreOutcome {
    pub source: PathBuf,
    pub destination: PathBuf,
    pub source_schema_version: u32,
    pub restored_schema_version: u32,
    pub byte_length: u64,
}

#[derive(Debug, Clone, Serialize)]
pub struct RetentionOutcome {
    pub directory: PathBuf,
    pub kept: usize,
    pub removed: Vec<PathBuf>,
}

pub fn restore_to(source: &Path, destination: &Path) -> Result<RestoreOutcome> {
    let source_schema_version = Store::validate_backup(source)?;
    if destination.exists() {
        return Err(Error::Conflict(format!(
            "restore destination {} already exists",
            destination.display()
        )));
    }
    let parent = destination.parent().ok_or_else(|| {
        Error::Invalid("restore destination must have a parent directory".to_owned())
    })?;
    fs::create_dir_all(parent)?;
    let file_name = destination
        .file_name()
        .and_then(|name| name.to_str())
        .ok_or_else(|| Error::Invalid("restore destination must have a file name".to_owned()))?;
    let temporary = parent.join(format!(".{file_name}.restore-{}.tmp", Uuid::now_v7()));
    let result = restore_via_temporary(source, destination, &temporary, source_schema_version);
    if result.is_err() {
        let _ = fs::remove_file(&temporary);
    }
    result
}

fn restore_via_temporary(
    source: &Path,
    destination: &Path,
    temporary: &Path,
    source_schema_version: u32,
) -> Result<RestoreOutcome> {
    let mut input = File::open(source)?;
    let mut output = OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(temporary)?;
    let byte_length = io::copy(&mut input, &mut output)?;
    output.sync_all()?;
    drop(output);

    Store::validate_backup(temporary)?;
    drop(Store::open(temporary)?);
    let restored_schema_version = Store::validate_backup(temporary)?;
    fs::rename(temporary, destination)?;

    Ok(RestoreOutcome {
        source: fs::canonicalize(source)?,
        destination: fs::canonicalize(destination)?,
        source_schema_version,
        restored_schema_version,
        byte_length,
    })
}

pub fn prune_backups(directory: &Path, keep: usize) -> Result<RetentionOutcome> {
    if keep == 0 || keep > 1_000 {
        return Err(Error::Invalid(
            "backup retention keep must be between 1 and 1000".to_owned(),
        ));
    }
    let directory = fs::canonicalize(directory)?;
    if !directory.is_dir() {
        return Err(Error::Invalid(
            "backup retention path must be a directory".to_owned(),
        ));
    }
    let mut candidates = fs::read_dir(&directory)?
        .filter_map(|entry| entry.ok())
        .filter_map(|entry| {
            let path = entry.path();
            let name = path.file_name()?.to_str()?;
            let metadata = fs::symlink_metadata(&path).ok()?;
            (metadata.is_file()
                && !metadata.file_type().is_symlink()
                && name.starts_with("aporic-backup-")
                && name.ends_with(".sqlite3"))
            .then_some((metadata.modified().ok(), path))
        })
        .collect::<Vec<_>>();
    candidates.sort();
    let remove_count = candidates.len().saturating_sub(keep);
    let mut removed = Vec::with_capacity(remove_count);
    for (_, path) in candidates.into_iter().take(remove_count) {
        fs::remove_file(&path)?;
        removed.push(path);
    }
    Ok(RetentionOutcome {
        directory,
        kept: keep,
        removed,
    })
}
use aporic::{
    Hub,
    domain::{OpenRequest, RecallRequest},
    recovery::{prune_backups, restore_to},
};

#[test]
fn restores_a_validated_backup_into_a_new_database() {
    let area = tempfile::tempdir().unwrap();
    let workspace = area.path().join("workspace");
    std::fs::create_dir(&workspace).unwrap();
    let source_database = area.path().join("source.sqlite3");
    let hub = Hub::open(&source_database).unwrap();
    hub.open_session(&OpenRequest {
        workspace: workspace.to_string_lossy().into_owned(),
        objective: "survive restore".to_owned(),
        idempotency_key: "restore-open".to_owned(),
    })
    .unwrap();
    let backup = area.path().join("aporic-backup-001.sqlite3");
    hub.backup_to(&backup).unwrap();
    let restored = area.path().join("restored.sqlite3");

    let outcome = restore_to(&backup, &restored).unwrap();
    assert_eq!(outcome.source_schema_version, 25);
    assert_eq!(outcome.restored_schema_version, 25);
    assert!(outcome.byte_length > 0);
    assert!(
        restore_to(&backup, &restored)
            .unwrap_err()
            .to_string()
            .contains("already exists")
    );

    let restored_hub = Hub::open(&restored).unwrap();
    let recalled = restored_hub
        .recall(&RecallRequest {
            workspace: workspace.to_string_lossy().into_owned(),
            objective: None,
            focus_paths: Vec::new(),
            limit: Some(20),
            max_bytes: Some(16_384),
        })
        .unwrap();
    assert_eq!(recalled.active_sessions.len(), 1);
}

#[test]
fn retention_only_removes_strictly_named_backup_files() {
    let area = tempfile::tempdir().unwrap();
    for name in [
        "aporic-backup-001.sqlite3",
        "aporic-backup-002.sqlite3",
        "aporic-backup-003.sqlite3",
        "unrelated.sqlite3",
    ] {
        std::fs::write(area.path().join(name), name).unwrap();
    }
    let outcome = prune_backups(area.path(), 2).unwrap();
    assert_eq!(outcome.removed.len(), 1);
    assert!(area.path().join("unrelated.sqlite3").exists());
    assert_eq!(
        std::fs::read_dir(area.path())
            .unwrap()
            .filter_map(Result::ok)
            .filter(|entry| entry
                .file_name()
                .to_string_lossy()
                .starts_with("aporic-backup-"))
            .count(),
        2
    );
}

#[test]
fn restore_rejects_an_unrelated_sqlite_database() {
    let area = tempfile::tempdir().unwrap();
    let unrelated = area.path().join("unrelated.sqlite3");
    let connection = rusqlite::Connection::open(&unrelated).unwrap();
    connection
        .execute("CREATE TABLE unrelated (value TEXT)", [])
        .unwrap();
    drop(connection);
    let destination = area.path().join("restored.sqlite3");

    let error = restore_to(&unrelated, &destination).unwrap_err();
    assert!(
        error
            .to_string()
            .contains("not a recognized Aporic database")
    );
    assert!(!destination.exists());
}
